const typeAttributeDefs = `-- name: TypeAttributeDefs :many
SELECT live_attribute_def.id, live_attribute_def.workspace_id, live_attribute_def.project_id, live_attribute_def.component_type_id, live_attribute_def."order", live_attribute_def.key, live_attribute_def.name, live_attribute_def.type, live_attribute_def.enum_options, live_attribute_def.default_value, live_attribute_def.is_runtime, live_attribute_def.rev, live_attribute_def.deleted_at, live_attribute_def.created_by, live_attribute_def.updated_by, live_attribute_def.created_at, live_attribute_def.updated_at FROM live_attribute_def
WHERE workspace_id = $1 AND project_id = $2 AND component_type_id = ANY($3::uuid[])
ORDER BY component_type_id, "order", id
`

type TypeAttributeDefsParams struct {
	WorkspaceID pgtype.UUID
	ProjectID   pgtype.UUID
	TypeIds     []pgtype.UUID
}

type TypeAttributeDefsRow struct {
	LiveAttributeDef LiveAttributeDef
}

// TypeAttributeDefs returns the attribute definitions that are not in the
// trash of the project's types whose IDs are among type_ids, by their types,
// each type's in their order: by their orders, then by their IDs.
func (q *Queries) TypeAttributeDefs(ctx context.Context, arg TypeAttributeDefsParams) ([]TypeAttributeDefsRow, error) {
	rows, err := q.db.Query(ctx, typeAttributeDefs, arg.WorkspaceID, arg.ProjectID, arg.TypeIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TypeAttributeDefsRow
	for rows.Next() {
		var i TypeAttributeDefsRow
		if err := rows.Scan(
			&i.LiveAttributeDef.ID,
			&i.LiveAttributeDef.WorkspaceID,
			&i.LiveAttributeDef.ProjectID,
			&i.LiveAttributeDef.ComponentTypeID,
			&i.LiveAttributeDef.Order,
			&i.LiveAttributeDef.Key,
			&i.LiveAttributeDef.Name,
			&i.LiveAttributeDef.Type,
			&i.LiveAttributeDef.EnumOptions,
			&i.LiveAttributeDef.DefaultValue,
			&i.LiveAttributeDef.IsRuntime,
			&i.LiveAttributeDef.Rev,
			&i.LiveAttributeDef.DeletedAt,
			&i.LiveAttributeDef.CreatedBy,
			&i.LiveAttributeDef.UpdatedBy,
			&i.LiveAttributeDef.CreatedAt,
			&i.LiveAttributeDef.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

